[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)]
    [ValidateSet('replay','compatibility','trial-plan','acceptance-report')]
    [string] $Operation,
    [Parameter(Mandatory = $true)]
    [string] $InputPath
)

$ErrorActionPreference = 'Stop'

function Read-Object { if (-not (Test-Path -LiteralPath $InputPath -PathType Leaf)) { throw 'Input file was not found.' }; try { $value=ConvertFrom-Json -InputObject (Get-Content -Raw -LiteralPath $InputPath) -AsHashtable -Depth 100 } catch { throw "Input is not valid JSON: $($_.Exception.Message)" }; if($value -isnot [System.Collections.IDictionary]){throw 'Input JSON must be an object.'};return $value }
function Need { param([System.Collections.IDictionary]$Object,[string]$Name);if(-not $Object.Contains($Name)-or $null -eq $Object[$Name]-or [string]::IsNullOrWhiteSpace([string]$Object[$Name])){throw "$Name is required."};return [string]$Object[$Name] }
function Read-Reference { param([System.Collections.IDictionary]$Reference,[string]$Name);$path=[IO.Path]::GetFullPath((Need $Reference 'path'));if(-not(Test-Path -LiteralPath $path -PathType Leaf)){throw "$Name file was not found."};$sha=[Security.Cryptography.SHA256]::Create();$stream=[IO.File]::OpenRead($path);try{$hash=([Convert]::ToHexString($sha.ComputeHash($stream))).ToLowerInvariant()}finally{$stream.Dispose();$sha.Dispose()};if(-not $Reference.Contains('sha256')-or [string]$Reference.sha256.ToLowerInvariant() -cne $hash){throw "$Name hash does not match."};try{$value=ConvertFrom-Json -InputObject (Get-Content -Raw -LiteralPath $path) -AsHashtable -Depth 100}catch{throw "$Name JSON is invalid."};return $value }

function Invoke-HelperIntegration { param([System.Collections.IDictionary]$Scenario)
    if (-not $Scenario.Contains('helperIntegration')) { return [ordered]@{verified=$false;cases=@()} }
    $root = Join-Path ([IO.Path]::GetTempPath()) ('TaigaMCP-acceptance-' + [Guid]::NewGuid().ToString('N')); [IO.Directory]::CreateDirectory($root) | Out-Null; $results=@()
    try {
        foreach($case in @($Scenario.helperIntegration)) {
            if ($case -isnot [System.Collections.IDictionary]) { throw 'Each helperIntegration case must be an object.' }
            foreach($name in @('name','script','operation','input','expect')){Need $case $name|Out-Null}
            $inputValue = $case.input; $caseRoot = $null
            if ($case.Contains('setup') -and [string]$case.setup -ceq 'expired-dispatch') {
                $caseRoot = Join-Path $root ([string]$case.name); [IO.Directory]::CreateDirectory($caseRoot) | Out-Null
                $stateScript = Join-Path $PSScriptRoot 'workflow-state.ps1'; $packetScript = Join-Path $PSScriptRoot 'workflow-packet.ps1'; $syntheticPath = Join-Path $PSScriptRoot '..\assets\synthetic-run.json'; $init = ConvertFrom-Json -InputObject (Get-Content -Raw -LiteralPath $syntheticPath) -AsHashtable -Depth 100; $init.sessionId = 'acceptance-deadline-session'; $initPath = Join-Path $root 'deadline-init.json'; [IO.File]::WriteAllText($initPath,($init|ConvertTo-Json -Depth 100),[Text.UTF8Encoding]::new($false)); $initLines=& pwsh -NoProfile -File $stateScript -Operation initialize-session -InputPath $initPath -StateRoot $caseRoot 2>&1; if($LASTEXITCODE -ne 0){throw 'Could not initialize the deadline helper workflow.'};$initResult=ConvertFrom-Json -InputObject ($initLines-join [Environment]::NewLine) -AsHashtable -Depth 100; $ticketKey='project:123:issue:99'; $claimPath=Join-Path $root 'deadline-claim.json'; [IO.File]::WriteAllText($claimPath,(@{sessionId=$init.sessionId;ownerGeneration=1;ticketKey=$ticketKey;repositoryIdentity='acceptance-repo';expectedRevision=$initResult.revision}|ConvertTo-Json -Depth 100),[Text.UTF8Encoding]::new($false));$claimLines=& pwsh -NoProfile -File $stateScript -Operation claim-ticket -InputPath $claimPath -StateRoot $caseRoot 2>&1;if($LASTEXITCODE -ne 0){throw 'Could not claim the deadline helper ticket.'};$claimResult=ConvertFrom-Json -InputObject ($claimLines-join [Environment]::NewLine) -AsHashtable -Depth 100;$repo=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\..'));$branch=(( & git -C $repo rev-parse --abbrev-ref HEAD).Trim());$head=(( & git -C $repo rev-parse HEAD).Trim());$contextPath=Join-Path $root 'deadline-context.txt';[IO.File]::WriteAllText($contextPath,'deadline helper context',[Text.UTF8Encoding]::new($false));$packetRequest=@{packetId='acceptance-deadline-packet';sessionId=$init.sessionId;runId='acceptance-deadline-run';ticket=@{ticketKey=$ticketKey;projectId=123;kind='issue';id=99;ref=99;title='Deadline helper'};contextPath=$contextPath;criteria=@(@{id='criterion-1';text='Block expired dispatch.'});repository=@{identity='acceptance-repo';repositoryPath=$repo;worktreePath=$repo;branch=$branch;baseSha=$head};requiredCommands=@('synthetic-check');unresolvedRequirements=@();authority=@{authorizedActions=@('dispatch');excludedActions=@()};deadline=@{startedAtUtc='2000-01-01T00:00:00Z';deadlineUtc='2000-01-01T00:01:00Z';elapsedBudgetMinutes=1};profiles=@{coordinator=@{model='gpt-6.1-sol';effort='high'};implementer=@{model='gpt-5.6-luna';effort='xhigh'};reviewer=@{model='gpt-6.1-sol';effort='high'}}};$packetPath=Join-Path $root 'deadline-packet-request.json';[IO.File]::WriteAllText($packetPath,($packetRequest|ConvertTo-Json -Depth 100),[Text.UTF8Encoding]::new($false));$packetLines=& pwsh -NoProfile -File $packetScript -Operation create -InputPath $packetPath -StateRoot $caseRoot 2>&1;if($LASTEXITCODE -ne 0){throw 'Could not create the expired helper packet.'};$packetResult=ConvertFrom-Json -InputObject ($packetLines-join [Environment]::NewLine) -AsHashtable -Depth 100;$packetFile=[string]$packetResult.data.packetPath;$inputValue=@{sessionId=$init.sessionId;ownerGeneration=1;ticketKey=$ticketKey;actionId='deadline-action';workerId='worker-thread';packetReference=@{path=$packetFile;sha256=(Get-FileHash -Algorithm SHA256 -LiteralPath $packetFile).Hash.ToLowerInvariant()}}
            }
            $inputPath=Join-Path $root (([IO.Path]::GetRandomFileName())+'.json');[IO.File]::WriteAllText($inputPath,($inputValue|ConvertTo-Json -Depth 100),[Text.UTF8Encoding]::new($false));$scriptPath=Join-Path $PSScriptRoot ([string]$case.script);if(-not(Test-Path -LiteralPath $scriptPath -PathType Leaf)){throw "Helper script was not found: $($case.script)"};$args=@('-NoProfile','-File',$scriptPath,'-Operation',[string]$case.operation,'-InputPath',$inputPath);if($case.Contains('usesStateRoot') -and $case.usesStateRoot -eq $true){if($null -eq $caseRoot){$caseRoot=Join-Path $root ([string]$case.name)};$args+=@('-StateRoot',$caseRoot)};$lines=& pwsh @args 2>&1;$exit=$LASTEXITCODE;$raw=$lines-join [Environment]::NewLine;try{$actual=ConvertFrom-Json -InputObject $raw -AsHashtable -Depth 100}catch{throw "Helper integration returned invalid JSON for $($case.name): $raw"};$expectedOk=($case.expect.ok -eq $true);if(($exit -eq 0) -ne $expectedOk -or ($actual.ok -eq $true) -ne $expectedOk){throw "Helper integration case failed: $($case.name)"};foreach($field in @('decision','reason','stateMutation')){if($case.expect.Contains($field)-and [string]$actual.data[$field] -cne [string]$case.expect[$field]){throw "Helper integration case $($case.name) did not produce expected $field."}};$results+=[ordered]@{name=[string]$case.name;operation=[string]$case.operation;ok=($actual.ok -eq $true);decision=if($actual.ok -eq $true){$actual.data.decision}else{$null};reason=if($actual.ok -eq $true){$actual.data.reason}else{$null}}
        }
        return [ordered]@{verified=$true;cases=$results}
    } finally { if(Test-Path -LiteralPath $root){Remove-Item -LiteralPath $root -Recurse -Force} }
}

function Invoke-Replay { param([System.Collections.IDictionary]$InputObject)
    $scenario=if($InputObject.Contains('scenarioReference')){Read-Reference $InputObject.scenarioReference 'scenario'}else{$InputObject};if([int]$scenario.schemaVersion -ne 1){throw 'Unsupported replay scenario version.'};foreach($name in @('runId','ticketKey','actions','events')){Need $scenario $name|Out-Null}
    $engineering=@($scenario.actions|Where-Object{$_.class -eq 'engineering' -and $_.actor -eq 'coordinator'});if($engineering.Count -gt 0){throw 'Replay contains coordinator engineering work.'}
    $workersByRole=@{};$workers=@();foreach($action in @($scenario.actions|Where-Object{$_.actor -in @('implementer','reviewer')})){if([string]::IsNullOrWhiteSpace([string]$action.workerId)){throw 'Engineering actions must identify their worker chat.'};$role=[string]$action.actor;if(-not $workersByRole.ContainsKey($role)){$workersByRole[$role]=[string]$action.workerId}elseif([string]$workersByRole[$role] -cne [string]$action.workerId){throw "Worker identity changed for $role during replay."};$workers+=[string]$action.workerId};$workers=@($workers|Select-Object -Unique)
    $events=@($scenario.events);$invalidEnums=@($events|Where-Object{$_.kind -eq 'finding' -and $_.disposition -notin @('open','fixed','rejected_accepted','escalated')});if($invalidEnums.Count -gt 0){throw 'Replay contains a noncanonical finding disposition.'};$missingRawExit=@($events|Where-Object{$_.kind -eq 'evidence' -and -not $_.Contains('rawExitCode')});if($missingRawExit.Count -gt 0){throw 'Replay evidence must retain the raw process exit code.'};$expiredDispatch=@($events|Where-Object{$_.kind -eq 'deadline' -and $_.dispatchAttempt -eq $true -and $_.allowed -eq $false});$invalidExpired=@($events|Where-Object{$_.kind -eq 'deadline' -and $_.dispatchAttempt -eq $true -and $_.expired -eq $true -and $_.allowed -ne $false});if($invalidExpired.Count -gt 0){throw 'Replay contains an expired dispatch that was allowed.'};$material=@($events|Where-Object{$_.kind -eq 'finding' -and ($_.severity -in @('high','critical') -or $_.material -eq $true) -and $_.disposition -eq 'open'});$publication=@($events|Where-Object{$_.kind -eq 'publication' -and ($_.accepted -eq $true -or $_.published -eq $true)});if($material.Count -gt 0 -and $publication.Count -gt 0){throw 'Replay published with unresolved material evidence.'};$waitMutations=@($events|Where-Object{$_.kind -eq 'wait' -and $_.mutatesState -eq $true}).Count;if($waitMutations -gt 0){throw 'Replay unchanged waits must not mutate state.'};$repairAttempts=@($events|Where-Object{$_.kind -eq 'receipt_repair'}).Count;if($repairAttempts -gt 2){throw 'Replay exceeds the bounded receipt repair limit.'};$copied=@($events|Where-Object{$_.kind -eq 'prompt' -and $_.fullReceiptCopied -eq $true}).Count;if($copied -gt 0){throw 'Replay cannot copy a complete receipt into a coordinator prompt.'};if(@($events|Where-Object{$_.kind -eq 'deadline'}).Count -eq 0){throw 'Replay must include deadline admission evidence.'};$helper=Invoke-HelperIntegration $scenario;return [ordered]@{offline=$true;nativeHostVerified=$false;accepted=$true;coordinatorEngineeringActions=$engineering.Count;workerIdsStable=$true;workerIds=$workers;publicationBlockedByMaterialEvidence=($material.Count -gt 0 -and $publication.Count -eq 0);repairAttempts=$repairAttempts;unchangedWaitMutations=$waitMutations;expiredDispatchesBlocked=$expiredDispatch.Count;rawExitEvidenceCount=$missingRawExit.Count -eq 0;enumValidation='canonical';helperIntegration=$helper}
}

function Invoke-Compatibility { param([System.Collections.IDictionary]$InputObject)
    if(-not $InputObject.Contains('records')){throw 'records must be supplied.'};$accepted=@();foreach($record in @($InputObject.records)){if($record.schemaVersion -notin @(1,2)){throw "Unsupported record schema version: $($record.schemaVersion)."};if(-not $record.Contains('ticketKey')-or -not $record.Contains('phase')){throw 'Legacy/current record is missing ownership or phase.'};if(-not $record.Contains('receipt')-or $record.receipt -isnot [System.Collections.IDictionary]){throw 'Legacy/current record must carry its complete receipt object.'};if(-not $record.Contains('evidence')-or $record.evidence -is [string] -or $record.evidence -isnot [System.Collections.IEnumerable]){throw 'Legacy/current record must carry its complete evidence array.'};if(-not $record.receipt.Contains('recordId')-or [string]::IsNullOrWhiteSpace([string]$record.receipt.recordId)){throw 'Receipt round-trip identity is required.'};if($record.uncertainAction -eq $true -and $record.actionReconciled -eq $true){throw 'An uncertain action cannot be marked reconciled without external evidence.'};$receiptCopy=ConvertFrom-Json -InputObject ($record.receipt|ConvertTo-Json -Depth 100) -AsHashtable -Depth 100;$evidenceCopy=ConvertFrom-Json -InputObject (@($record.evidence)|ConvertTo-Json -Depth 100) -AsHashtable -Depth 100;$accepted+=[ordered]@{schemaVersion=[int]$record.schemaVersion;ticketKey=[string]$record.ticketKey;phase=[string]$record.phase;preservedReceipt=($receiptCopy.recordId -ceq $record.receipt.recordId);preservedEvidence=(@($evidenceCopy).Count -eq @($record.evidence).Count);receipt=$receiptCopy;evidence=@($evidenceCopy);ownerGeneration=$record.ownerGeneration}};return [ordered]@{compatible=$true;records=$accepted;rollback='unsupported_versions_fail_closed';actualRunMigrated=$false}
}

function Invoke-TrialPlan { param([System.Collections.IDictionary]$InputObject)
    foreach($name in @('ticketKey','repository','workerProfiles','authorization','stopConditions')){Need $InputObject $name|Out-Null};if($InputObject.workerProfiles.implementer.model -cne 'gpt-5.6-luna'-or $InputObject.workerProfiles.implementer.effort -cne 'xhigh'-or $InputObject.workerProfiles.reviewer.model -cne 'gpt-6.1-sol'-or $InputObject.workerProfiles.reviewer.effort -cne 'high'){throw 'Trial must name the exact worker profiles.'};if($InputObject.authorization.createChats -ne $true -or $InputObject.authorization.messageWorkers -ne $true){throw 'Trial authorization must explicitly cover ordinary chats and worker messages.'};return [ordered]@{ready=$true;nativeOperationsRequired=@('create_or_reuse_ordinary_chats','message_same_worker_chats','wait_threads','automation_update');ticketKey=[string]$InputObject.ticketKey;repository=[string]$InputObject.repository;workerProfiles=$InputObject.workerProfiles;automaticMerge=$false;publicationOnlyIfAuthorized=$true;stopConditions=@($InputObject.stopConditions);executes=$false}
}

function Invoke-Report { param([System.Collections.IDictionary]$InputObject)
    if(-not $InputObject.Contains('offlineGates')){throw 'offlineGates must be supplied.'};$offline=@($InputObject.offlineGates);$offlinePassed=(@($offline|Where-Object{$_ -eq $true}).Count -eq $offline.Count -and $offline.Count -gt 0);$hostVerified=($InputObject.actualHostVerified -eq $true);$publicationVerified=($InputObject.publicationVerified -eq $true);return [ordered]@{offlineAccepted=$offlinePassed;actualHostVerified=$hostVerified;publicationVerified=$publicationVerified;overallOperationalAcceptance=($offlinePassed -and $hostVerified -and $publicationVerified);pendingGates=@(if(-not $hostVerified){'actual_host_trial'};if(-not $publicationVerified){'publication_exercise'});qualityEvidence=$InputObject.qualityEvidence;costEvidence=$InputObject.costEvidence;rawTokensAreNotAcceptanceGate=$true}
}

try{$inputObject=Read-Object;$data=switch($Operation){'replay'{Invoke-Replay $inputObject};'compatibility'{Invoke-Compatibility $inputObject};'trial-plan'{Invoke-TrialPlan $inputObject};'acceptance-report'{Invoke-Report $inputObject}};[ordered]@{ok=$true;operation=$Operation;data=$data}|ConvertTo-Json -Depth 100;exit 0}catch{[ordered]@{ok=$false;operation=$Operation;error=[ordered]@{category='workflow_acceptance';message=$_.Exception.Message}}|ConvertTo-Json -Depth 20;exit 1}
